:root {
  --paper: #fffdf6;
  --ink: #26352b;
  --muted: #718074;
  --line: #d8dfcc;
  --moss: #466b48;
  --moss-dark: #2f5035;
  --sage: #edf2e5;
  --gold: #d9a83f;
}

.banding-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background-color: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--moss);
  border-radius: 14px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.heading-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.card-title {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.band-id {
  padding: 5px 8px;
  color: var(--moss-dark);
  background-color: var(--sage);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}

.bird-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 0;
}

.bird-mark {
  display: grid;
  width: 42px;
  height: 42px;
  margin: 0;
  place-items: center;
  background-color: var(--sage);
  border-radius: 50%;
  font-size: 23px;
}

.bird-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.species {
  margin: 0;
  font-size: 16px;
  line-height: 1.15;
}

.details {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.metric {
  padding: 8px 11px;
  border-right: 1px solid var(--line);
}

.metric:last-child {
  border-right: 0;
}

.metric dt {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.metric dd {
  margin: 2px 0 0;
  font-size: 14px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 13px;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--moss-dark);
  font-size: 13px;
  font-weight: 700;
}

.status-dot {
  width: 8px;
  height: 8px;
  background-color: var(--gold);
  border-radius: 50%;
}

.release-button {
  padding: 7px 11px;
  color: var(--paper);
  background-color: var(--moss);
  border: 0;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}
